class PendingJob {
  constructor(fromApp, fromPage, fromComponent, payload, operation, metaData, entity_name, display_name, dependencyID, dependencyFieldName) {
    this.context_from_app = fromApp;
    this.context_from_page = fromPage;
    this.context_from_component = fromComponent;
    this.display_name = display_name;

    this.payload = payload;
    this.operation = operation;
    this.metaData = metaData;
    this.entity_name = entity_name;

    this.id = PendingJob.generateUUID();
    this.createDate = moment().format("yyyy-MM-D HH:mm:ss");
    this.status = 'PENDING';

    this.dependency = {
      id: dependencyID,
      field_name: dependencyFieldName
    };

    this.processingStart = undefined;
    this.processingEnd = undefined;
    this.result = undefined;
  }

  static generateUUID() {
      return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
          const r = Math.random() * 16 | 0;
          const v = c === 'x' ? r : (r & 0x3 | 0x8);
          return v.toString(16);
      });
  }
}

class JobQueue {

