  static addJob(job)
  {
    //Need to check if ID is unique or not

    let jobQueue = localStorage.getValue(this.QUEUE_KEY) || [];
    jobQueue.push(job);

    localStorage.setValue(this.QUEUE_KEY, jobQueue);
  }

  static updateJob(job)
  {
    //Need to check if ID is unique or not

    let jobQueue = localStorage.getValue(this.QUEUE_KEY) || [];
    let index = jobQueue.findIndex((x) => x.id == job.id);

    if (index > -1)
