  static postgreSPToObject(sql) {
    const result = {};

    // Extract everything inside the parentheses
    const inner = sql.replace(/^[\s\S]*?\(/, "").replace(/\)[\s\S]*$/, "");

    // Split by lines to avoid breaking on commas inside values
    const lines = inner.split(/\r?\n/);

    for (let rawLine of lines) {
      const line = rawLine.trim();

      // Skip empty lines
      if (!line) continue;

      // Remove trailing comma
      const cleaned = line.replace(/,$/, "");

      // Match: param_name => value
      const match = cleaned.match(/^([a-zA-Z0-9_]+)\s*=>\s*(.*)$/);
      if (!match) continue;

      const key = match[1];
      let value = match[2].trim();

      // Handle empty values → undefined
      if (value === "" || value === "null") {
        result[key] = undefined;
        continue;
      }

      // Handle quoted strings
      if ((value.startsWith("'") && value.endsWith("'")) ||
          (value.startsWith('"') && value.endsWith('"'))) {
        result[key] = value.slice(1, -1);
        continue;
      }

      // Convert booleans
      if (value === "true") {
        result[key] = true;
        continue;
      }
      if (value === "false") {
        result[key] = false;
        continue;
      }

      // Otherwise treat as raw literal (UUID, number, date, etc.)
      result[key] = value;
    }

    return result;
  }
}
